// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.17;
import {Test} from "forge-std/Test.sol";
import {RoundFactory} from "../src/RoundFactory.sol";

contract InvMutTest is Test {
    RoundFactory c;
    address originalOwner;

    function setUp() public {
        c = new RoundFactory();
        c.initialize();
        originalOwner = address(this);
    }

    function testFuzz_property(address newOwner, address caller) public {
        vm.assume(newOwner != address(0));
        vm.assume(caller != address(this));

        c.transferOwnership(newOwner);

        vm.prank(caller);
        address observedOwner = c.owner();

        assertTrue(observedOwner == newOwner);
    }
}
